// Step 2: Deterministic Pre-Classification Filter (P0-3 Approval Safety)
const item = $input.first().json;
const subject = (item.subject || '').trim();
const body = (item.bodyPreview || item.body?.content || '').trim();
const fromAddress = item.from?.emailAddress?.address || '';

// Explicit approval intent patterns (strict, excludes generic 'Re: Quote')
const approvalPatterns = [
  /quote\s*(is\s*)?approved/i,
  /approve\s*(the\s*)?quote/i,
  /quote\s*accepted/i,
  /accept\s*(the\s*)?quote/i,
  /partial\s*approval/i,
  /approved\s*up\s*to\s*([£$€]?\d+)/i,
  /proceed\s*with\s*(the\s*)?(quote|work|repair)/i,
  /go\s*ahead\s*with\s*(the\s*)?quote/i,
  /approval\s*confirmed/i,
  /customer\s*(accepts|approves)\s*quote/i
];

const hasDeterministicApproval = approvalPatterns.some(p => p.test(subject) || p.test(body));

return [{
  json: {
    messageId: item.id,
    internetMessageId: item.internetMessageId || item.id,
    subject: subject,
    bodySnippet: body.substring(0, 4000),
    fromEmail: fromAddress,
    fromName: item.from?.emailAddress?.name || '',
    hasAttachments: Boolean(item.hasAttachments),
    isDeterministicApproval: hasDeterministicApproval
  }
}];

// Deterministic Approval Detected: STOP immediately & Leave UNREAD in Outlook
console.log(`[Approval Filter] Blocked approval email: '${$json.subject}'. Leaving UNREAD for manual review.`);
return [];

// Quality gate failed (Low confidence, approval, missing fields, or missing fromEmail)
console.log(`[Quality Gate] Rejected: State='${$json.classification_state}', Confidence=${$json.confidence_score}. Leaving UNREAD for manual review.`);
return [];

// P1-2: Backend returned a non-success status (400/401/403/409/422/500/timeout/malformed).
// Email must remain UNREAD for manual investigation.
console.log(`[Backend Success Gate] Backend returned status ${$json.statusCode}. Email left UNREAD.`);
return [];
